class Solution {
public:
    int distinctPoints(string s, int k) {
        int n = (int)s.size();
        vector<int> px(n + 1, 0), py(n + 1, 0);
        for (int i = 0; i < n; i++) {
            px[i + 1] = px[i];
            py[i + 1] = py[i];
            char c = s[i];
            if (c == 'L') px[i + 1] -= 1;
            else if (c == 'R') px[i + 1] += 1;
            else if (c == 'U') py[i + 1] += 1;
            else if (c == 'D') py[i + 1] -= 1;
        }
        int totalX = px[n];
        int totalY = py[n];
        unordered_set<long long> seen;
        seen.reserve(n - k + 1);
        for (int i = 0; i + k <= n; i++) {
            int x = px[i] + (totalX - px[i + k]);
            int y = py[i] + (totalY - py[i + k]);
            long long key = ((long long)(x + n) << 32) | (unsigned int)(y + n);
            seen.insert(key);
        }
        return (int)seen.size();
    }
};
